import React from "react";
import styled from "styled-components";
import TypeButton from "./button/TypeButton";

const SelectTypeWrapper = styled.div`
  margin-bottom: 50px;
`;

const Label = styled.label`
  display: block;
  margin-bottom: 10px;
  font-size: ${(prop) => prop.theme.fonts.mediumText};
  font-weight: ${(prop) => prop.theme.fontWeight.smallText};
`;

const BtnBox = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
`;

interface SelectTypeProps {
  label: string;
  typeList: string[];
  type: string;
  setType: (type: string) => void;
  flex?: boolean;
  text?: boolean;
  paragraph?: boolean;
}

const SelectType: React.FC<SelectTypeProps> = ({
  type,
  label,
  typeList,
  setType,
  flex,
  text,
  paragraph,
}) => {
  return (
    <SelectTypeWrapper>
      <Label>{label}</Label>
      <BtnBox>
        {typeList.map((item, index) => (
          <TypeButton
            key={index}
            type={item}
            selectedType={type}
            setType={(type) => setType(type)}
            flex={flex}
            text={text}
            paragraph={paragraph}
          />
        ))}
      </BtnBox>
    </SelectTypeWrapper>
  );
};

export default SelectType;
