interface UserData {
  id: number;
  user_name: string;
  job_name: string;
  job_description: string;
  related_major: string;
  certifications: string;
  recommendation_reason: string;
  user_id: number;
}

const CustomizedCareer = () => {
  const [openSection, setOpenSection] = useState(null);
  const [useResult, setUseResult] = useState<UserData | null>(null);
  const [isBookmarking, setIsBookmarking] = useState(false);
  const [userId, setUserId] = useState<number | null>(null);
  const [bookId, setBookId] = useState<number | null>(null);

  useEffect(() => {
    const userIdFromLocalStorage = localStorage.getItem("user_id");
    const userDataFromLocalStorage = localStorage.getItem("userData");

    if (userIdFromLocalStorage !== null) {
      setUserId(parseInt(userIdFromLocalStorage, 10));
    }

    if (userDataFromLocalStorage !== null) {
      const parsedUserData = JSON.parse(userDataFromLocalStorage);
      setBookId(parsedUserData.id);
    }
  }, []);
  useEffect(() => {
    const fetchData = async () => {
      const storedUserData = localStorage.getItem("userData");
      if (storedUserData !== null) {
        try {
          const response = JSON.parse(storedUserData);
          setUseResult(response);
          // userData를 사용하여 필요한 작업 수행
        } catch (error) {
          console.error("JSON 파싱 오류:", error);
        }
      } else {
        console.log("No user data found in localStorage");
      }
    };

    fetchData(); // 비동기 함수 호출
  }, []);
  const carrerData = {
    name: useResult && useResult.user_name,
    job: useResult && useResult.job_name,
    des: useResult && useResult.job_description,
    department: useResult && useResult.related_major,
    certificate: useResult && useResult.certifications,
    reason: useResult && useResult.recommendation_reason,
  };

  const accordionSections = [
    {
      header: "관련 학과",
      content: carrerData.department,
    },
    {
      header: "관련 자격증",
      content: carrerData.certificate,
    },
    {
      header: "왜 이 커리어가 추천 되었나요?",
      content: carrerData.reason,
    },
  ];
  const toggleAccordion = (index: any) => {
    setOpenSection((prevOpenSection) => (prevOpenSection === index ? null : index));
  };
  // 북마크

  const handleBookmarkClick = async () => {
    console.log(JSON.stringify(useResult));
    try {
      setIsBookmarking(true);
      const response = await axios.post(
        `http://49.50.166.153:8080/mypage/bookmarked-job/${userId}/`,
        JSON.stringify(useResult)
      );
      console.log(response);
    } catch (error) {
      console.error("Error bookmarking job:", error);
    }
  };

  const deleteBookmarkClick = async () => {
    try {
      setIsBookmarking(false);
      const response = await axios.delete(
        `http://49.50.166.153:8080/mypage/bookmarked-job/${userId}/${bookId}`
      );
      console.log(response);
    } catch (error) {
      console.error("Error bookmarking job:", error);
    }
  };

  const handleBookmarkAction = () => {
    // This function will be used as the onClick handler
    if (isBookmarking) {
      deleteBookmarkClick();
    } else {
      handleBookmarkClick();
    }
  };

  return (
    <AiWrapper>
      <Heading onClick={handleBookmarkAction} isBookmarking={isBookmarking} />
      <Replay />
      <Wrapper>
        <SloganBox>
          <Title title={`${useResult?.user_name} 님의`} />
          <Title title="맞춤 커리어 분석 결과에요" />
        </SloganBox>
      </Wrapper>
      <ContentBox>
        <AiChat>
          <Character>
            <img src={process.env.PUBLIC_URL + "/image/resultCharacter.png"} alt="characterImage" />
          </Character>
          <Link to={"/chat"}>
            <ChatBot>커리어 챗봇 연결</ChatBot>
          </Link>
        </AiChat>
        <ResultBox>
          <CareerBox>
            <Job>{carrerData.job}</Job>
            <Des> {carrerData.des}</Des>
          </CareerBox>
          <AccordionContainer>
            {accordionSections.map((section, index) => (
              <AccordionSection key={index}>
                <AccordionHeader onClick={() => toggleAccordion(index)}>
                  {section.header}
                  <Icon>{openSection === index ? <FaAngleUp /> : <FaAngleDown />}</Icon>
                </AccordionHeader>
                <AccordionContent $isOpen={openSection === index}>{section.content}</AccordionContent>
              </AccordionSection>
            ))}
          </AccordionContainer>
        </ResultBox>
      </ContentBox>
    </AiWrapper>
  );
};

export default CustomizedCareer;
