import { configureStore } from "@reduxjs/toolkit";
import { userIdSlice } from "./reducer/userIdSlice";
import { userResultSlice } from "./reducer/userResultSlice";

export default configureStore({
  reducer: {
    userIdSlice: userIdSlice.reducer,
    userResultSlice: userResultSlice.reducer,
  },
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      immutableCheck: true, // 불변성 체크 활성화
      serializableCheck: false, // 직렬화 체크 비활성화
    }),
});
