import { createSlice, PayloadAction } from "@reduxjs/toolkit";

// 숫자로 초기화된 initialState
const initialState = 0; // 또는 다른 숫자로 초기화

export const userIdSlice = createSlice({
  name: "setUserId",
  initialState,
  reducers: {
    setUserIdSlice: (state, action: PayloadAction<number>) => {
      // action.payload가 숫자이므로 새로운 상태로 업데이트
      return action.payload;
    },
  },
});

// action 생성자를 가져오지 않도록 변경
export const { setUserIdSlice } = userIdSlice.actions;

// 리듀서를 가져오지 않도록 변경
export default userIdSlice.reducer;
