import React, { useEffect, useState } from "react";
import ActionButton from "src/component/button/ActionButton";
import SelectType from "src/component/SelectType";
import InputType from "src/component/input/InputType";
import Slogan from "src/component/Slogan";
import { Wrapper } from "src/component/style/ Wrapper";
import axios from "axios";
import Heading from "src/component/Heading";

const genderList = ["남자", "여자"];
const ageList = ["20대", "30대", "40대", "50대", "60대"];
const tasteList = [
  "창작과 예술을 좋아해요",
  "운동과 액티비티를 즐겨요.",
  "학습과 감상을 즐겨요",
  "커뮤니티 활동을 좋아해요",
];

const Profile = () => {
  const [name, setName] = useState("");
  const [gender, setGender] = useState("");
  const [age, setAge] = useState("");
  const [aboutMe, setAboutMe] = useState("");
  const [isButtonActive, setIsButtonActive] = useState(false);
  const [userId, setUserId] = useState<number | null>(null);
  useEffect(() => {
    // 모든 선택 항목이 채워졌을 때 버튼 활성화
    if (name && gender && age && aboutMe) {
      setIsButtonActive(true);
    } else {
      setIsButtonActive(false);
    }
  }, [name, gender, age, aboutMe]);

  const handleNicknameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setName(event.target.value);
  };

  const apiEndpoint = "http://49.50.166.153:8080/profiles/info1/";

  // user data 전송
  const saveUserData = async () => {
    const requestData = {
      name,
      gender,
      age: parseInt(age.replace("대", "")),
      about_me: aboutMe,
    };
    console.log(JSON.stringify(requestData));
    try {
      const response = await axios.post(apiEndpoint, JSON.stringify(requestData));
      localStorage.setItem("user_id", response.data.user_id);
      setUserId(response.data.user_id);
    } catch (error) {
      console.error("에러:", error);
    }
  };
  // 서버에서 지난 데이터 요청
  const fetchUserData = async () => {
    try {
      // 저장된 사용자 ID를 사용하여 서버에서 사용자 데이터를 가져옵니다.
      const response = await axios.get(`http://49.50.166.153:8080/profiles/info1/${userId}/`);
      // 여기서 서버에서 받은 데이터를 필요에 따라 처리합니다.
      const userData = response.data;
      console.log("서버에서 받은 사용자 데이터:", userData);
    } catch (error) {
      console.error("에러:", error);
    }
  };

  return (
    <>
      <Heading />
      <Wrapper>
        <Slogan title="프로필을 입력해주세요!" subTitle="맞춤 커리어 가이드를 위한 과정이에요." />
        <InputType
          type="text"
          label="이름"
          value={name}
          onChange={handleNicknameChange}
          placeholder="이름 입력"
        />
        <SelectType typeList={genderList} label="성별" type={gender} setType={setGender} text />
        <SelectType typeList={ageList} label="나이" type={age} setType={setAge} text />
        <SelectType
          typeList={tasteList}
          label="저는요-"
          type={aboutMe}
          setType={setAboutMe}
          flex
          paragraph
        />
        <ActionButton src="/track" action="계속하기" disabled={!isButtonActive} onClick={saveUserData} />
      </Wrapper>
    </>
  );
};

export default Profile;
