import React, { useEffect, useState } from "react";
import ActionButton from "src/component/button/ActionButton";
import AttentionButton from "src/component/button/AttentionButton";
import Slogan from "src/component/Slogan";
import styled from "styled-components";
import { Wrapper } from "src/component/style/ Wrapper";
import axios from "axios";
import { useSelector } from "react-redux";
import { setUserIdSlice } from "src/store/reducer/userIdSlice";
import Heading from "src/component/Heading";

const Category = styled.div`
  margin-bottom: 100px;
  display: flex;
  flex-wrap: wrap;
`;

const categories = [
  "📊 경영·기획",
  "💻 개발",
  "📉 데이터",
  "🎨 디자인",
  "📚 교육",
  "🔬 연구개발",
  "💰 금융·재무",
  "💊 의약",
  "🎞️ 미디어·홍보",
  "🌟 생산관리·품질관리",
  "✍🏻 법률·법무",
  "🏷️ 생산·제조",
  "💡 마케팅·시장조사",
  "👤 인사·총무",
  "💬 서비스·고객지원",
  "🌐 유통·무역",
  "⚙️ 엔지니어링",
  "💼 영업·제휴",
];
type RequestData = {
  user_id: number | null;
  interest1: string;
  interest2: string;
  interest3: string;
};
const Track = () => {
  const [selectedCategories, setSelectedCategories] = useState<string[]>([]);
  const [isButtonActive, setIsButtonActive] = useState(false);
  const [userId, setUserId] = useState<number | null>(null);

  useEffect(() => {
    const userIdFromLocalStorage = localStorage.getItem("user_id");
    if (userIdFromLocalStorage !== null) {
      setUserId(parseInt(userIdFromLocalStorage, 10));
    }
  }, []);

  useEffect(() => {
    // 모든 선택 항목이 채워졌을 때 버튼 활성화
    if (selectedCategories.length === 3) {
      setIsButtonActive(true);
    } else {
      setIsButtonActive(false);
    }
  }, [selectedCategories]);

  const toggleCategory = (category: string) => {
    if (selectedCategories.includes(category)) {
      setSelectedCategories(selectedCategories.filter((c) => c !== category));
    } else {
      if (selectedCategories.length < 3) {
        setSelectedCategories([...selectedCategories, category]);
      } else {
        alert("최대 3개까지만 선택할 수 있습니다.");
      }
    }
  };
  const apiEndpoint = "http://49.50.166.153:8080/profiles/info2/";

  const saveUserData = async () => {
    const requestData: RequestData = {
      user_id: userId,
      interest1: selectedCategories[0].replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]|\s/g, ""),
      interest2: selectedCategories[1].replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]|\s/g, ""),
      interest3: selectedCategories[2].replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]|\s/g, ""),
    };

    console.log(JSON.stringify(requestData));
    try {
      const response = await axios.post(apiEndpoint, JSON.stringify(requestData));
      console.log(response);
    } catch (error) {
      console.error("에러:", error);
    }
  };

  return (
    <>
      <Heading />
      <Wrapper>
        <Slogan
          title="흥미 분야를 선택해 주세요!"
          subTitle={`세부 관심 분야를 파악하기 위한 과정이에요. (${selectedCategories.length}/3)`}
        />
        <Category>
          {categories.map((item) => (
            <AttentionButton
              key={item}
              isSelected={selectedCategories.includes(item)}
              onClick={() => toggleCategory(item)}
            >
              {item}
            </AttentionButton>
          ))}
        </Category>

        <ActionButton
          src="/education"
          action="계속하기"
          disabled={!isButtonActive}
          onClick={saveUserData}
        />
      </Wrapper>
    </>
  );
};

export default Track;
