import { Provider } from "react-redux";
import { Route, Routes, useLocation } from "react-router-dom";
import styled, { ThemeProvider } from "styled-components";
import HomeGnb from "./component/HomeGnb";
import BookMark from "./page/BookMark";
import Chat from "./page/Chat";
import CustomizedCareer from "./page/CustomizedCareer";
import Education from "./page/Education";
import Experience from "./page/Experience";
import Home from "./page/Home";
import Keyword from "./page/Keyword";
import Loading from "./page/Loading";
import Profile from "./page/Profile";
import Track from "./page/Track";
import configStore from "./store/configStore";

import theme from "./style/Theme";
const Wrap = styled.div``;

function App() {
  const location = useLocation();
  const isHome = location.pathname === "/";

  return (
    <Provider store={configStore}>
      <ThemeProvider theme={theme}>
        <Wrap>
          {isHome ? <HomeGnb logo="RECRUTAM" /> : null}
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/profile" element={<Profile />} />
            <Route path="/track" element={<Track />} />
            <Route path="/education" element={<Education />} />
            <Route path="/experience" element={<Experience />} />
            <Route path="/keyword" element={<Keyword />} />
            <Route path="/loading" element={<Loading />} />
            <Route path="/customizedCareer" element={<CustomizedCareer />} />
            <Route path="/chat" element={<Chat />} />
            <Route path="/bookmark" element={<BookMark />} />
          </Routes>
        </Wrap>
      </ThemeProvider>
    </Provider>
  );
}

export default App;
