import axios from "axios";
import React, { useEffect, useState } from "react";
import { useSelector } from "react-redux";
import ActionButton from "src/component/button/ActionButton";
import AttentionButton from "src/component/button/AttentionButton";
import Heading from "src/component/Heading";
import Slogan from "src/component/Slogan";
import { Wrapper } from "src/component/style/ Wrapper";
import { setUserIdSlice } from "src/store/reducer/userIdSlice";
import styled from "styled-components";

const Notice = styled.div`
  padding: 15px;
  margin-bottom: 20px;
  background-color: ${(prop) => prop.theme.colors.blue100};
  text-align: center;
  font-size: ${(prop) => prop.theme.fonts.smallText};
  font-weight: ${(prop) => prop.theme.fontWeight.smallText};
  color: ${(prop) => prop.theme.colors.blue600};
`;

const Category = styled.div`
  margin-bottom: 100px;
  display: flex;
  flex-wrap: wrap;
`;

type CategoriesData = {
  [key: string]: { id: number; keyword: string }[];
};

const Keyword = () => {
  const [selectedKeywordsWithType, setSelectedKeywordsWithType] = useState<
    { keyword: string; type: string }[]
  >([]);

  const [isButtonActive, setIsButtonActive] = useState(false);
  const [noticeText, setNoticeText] = useState(
    `10개 이상 선택해주세요! (${selectedKeywordsWithType.length}/20)`
  );

  const [categoriesData, setCategoriesData] = useState<CategoriesData>({});
  const [userId, setUserId] = useState<number | null>(null);

  useEffect(() => {
    const userIdFromLocalStorage = localStorage.getItem("user_id");
    if (userIdFromLocalStorage !== null) {
      setUserId(parseInt(userIdFromLocalStorage, 10));
    }
  }, []);
  useEffect(() => {
    fetchKeyword();
  }, []);

  useEffect(() => {
    // 모든 선택 항목이 채워졌을 때 버튼 활성화
    if (selectedKeywordsWithType.length > 9) {
      setIsButtonActive(true);
      setNoticeText(
        `더 많은 키워드로 정확한 분석을 받아보세요! (${selectedKeywordsWithType.length}/20)`
      );
    } else {
      setIsButtonActive(false);
      setNoticeText(`10개 이상 선택해주세요! (${selectedKeywordsWithType.length}/20)`);
    }
  }, [selectedKeywordsWithType]);

  const toggleCategory = (keyword: string, type: string) => {
    const isSelected = selectedKeywordsWithType.some((kw) => kw.keyword === keyword && kw.type === type);

    if (isSelected) {
      setSelectedKeywordsWithType(
        selectedKeywordsWithType.filter((kw) => !(kw.keyword === keyword && kw.type === type))
      );
    } else {
      if (selectedKeywordsWithType.length < 20) {
        setSelectedKeywordsWithType([...selectedKeywordsWithType, { keyword, type }]);
      } else {
        alert("최대 20개까지만 선택할 수 있습니다.");
      }
    }
  };
  // 실제 API 엔드포인트를 지정합니다.
  const apiEndpoint = "http://49.50.166.153:8080/profiles/info5/";
  // 서버에서 키워드 데이터 요청
  const fetchKeyword = async () => {
    try {
      // 저장된 사용자 ID를 사용하여 서버에서 사용자 데이터를 가져옵니다.
      const response = await axios.get(apiEndpoint);
      // 여기서 서버에서 받은 데이터를 필요에 따라 처리합니다.
      setCategoriesData(response.data);

      console.log("서버에서 받은 사용자 데이터:", response);
    } catch (error) {
      console.error("에러:", error);
    }
  };

  const renderKeywords = () => {
    return Object.keys(categoriesData).map((type) => (
      <div key={type}>
        {categoriesData[type].map((item: { id: number; keyword: string }) => (
          <AttentionButton
            key={item.id}
            isSelected={selectedKeywordsWithType.some(
              (kw) => kw.keyword === item.keyword && kw.type === type
            )}
            onClick={() => toggleCategory(item.keyword, type)}
          >
            {item.keyword}
          </AttentionButton>
        ))}
      </div>
    ));
  };
  // user keyword 전송
  const saveUserData = async () => {
    const requestData = {
      user_id: userId,
      user_keywords: selectedKeywordsWithType,
    };
    console.log(JSON.stringify(requestData));
    try {
      const response = await axios.post(
        "http://49.50.166.153:8080/profiles/info5/",
        JSON.stringify(requestData)
      );
      console.log(response);
    } catch (error) {
      console.error("에러:", error);
    }
  };

  return (
    <>
      <Heading />
      <Wrapper>
        <Slogan
          title="나의 성향에 맞는 키워드를 선택해주세요!"
          subTitle="맞춤 가이드를 위한 마지막 단계에요."
          style={{ marginBottom: "0" }}
        />
      </Wrapper>
      <Notice>{noticeText} </Notice>
      <Wrapper>
        <Category>{renderKeywords()}</Category>
        <ActionButton
          src="/Loading"
          action="AI 맞춤 커리어 보러가기"
          disabled={!isButtonActive}
          onClick={saveUserData}
        />
      </Wrapper>
    </>
  );
};

export default Keyword;
