import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Wrapper } from "src/component/style/ Wrapper";
import SubTitle from "src/component/text/SubTitle";
import Title from "src/component/text/Title";
import styled, { keyframes } from "styled-components";
import { FaCircleCheck } from "react-icons/fa6";
import axios from "axios";
import { useDispatch, useSelector } from "react-redux";
import { setUserIdSlice } from "src/store/reducer/userIdSlice";

const ContentBox = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 100vh;
`;

const bounce = keyframes`
  0%, 20%, 50%, 80%, 100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-30px);
  }
  60% {
    transform: translateY(-15px);
  }
  
`;

const Character = styled.div`
  width: 100px;
  height: 100px;
  margin-bottom: 40px;
  animation: ${bounce} 2s infinite;
`;

const colorChange = keyframes`
  0% {
    color:#CCCCCC;
  }
  100% {
    color:#60A5FA;
  }
`;

const ProccessBox = styled.div`
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-top: 30px;
`;

const Proccess = styled.div`
  display: flex;
  color: ${(prop) => prop.theme.colors.gray400};
  gap: 10px;
  align-items: center;
  animation: ${colorChange} 2s linear forwards;
  :first-child {
    font-size: ${(prop) => prop.theme.fonts.waitingDescription};
  }
  &:nth-child(1) {
    animation-delay: 2s;
  }
  &:nth-child(2) {
    animation-delay: 4s;
  }
  &:nth-child(3) {
    animation-delay: 6s;
  }
  &:nth-child(4) {
    animation-delay: 8s;
  }
  &:nth-child(5) {
    animation-delay: 10s;
  }
`;

const profileAnalysisSteps = [
  "프로필을 읽고 있어요.",
  "관심 분야를 분석하고 있어요.",
  "가까운 단어를 분석하고 있어요.",
  "학력 · 적성을 분석하고 있어요.",
  "경험을 적용하고 있어요.",
];

type UserData = {
  profile: {
    id: number;
    name: string;
    gender: string;
    age: number;
    about_me: string;
  };
  education: {
    id: number;
    user_id: number;
    education: string;
    major: string;
    major_check: string;
  }[];
  experience: {
    id: number;
    user_id: number;
    experience_type: string;
    experience_content: string;
  }[];
  interest: {
    id: number;
    user_id: number;
    interest1: string;
    interest2: string;
    interest3: string;
  }[];
  keyword: {
    id: number;
    user_id: number;
    keyword: string;
    type: string;
  }[];
};

type TransformedDataItem = {
  role: string;
  content: string;
};

const Loading = () => {
  const [userId, setUserId] = useState<number | null>(null);

  useEffect(() => {
    const userIdFromLocalStorage = localStorage.getItem("user_id");
    if (userIdFromLocalStorage !== null) {
      setUserId(parseInt(userIdFromLocalStorage, 10));
    }
  }, []);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchDataAndSave = async () => {
      try {
        const response = await fetchUserData();
        const transformedData = await transformUserData(response);
        saveUserData(transformedData);
      } catch (error) {
        console.error("에러:", error);
      }
    };

    fetchDataAndSave();

    const timer = setTimeout(() => {
      // 15초 후에 "/"로 페이지 이동
    }, 15000);

    return () => clearTimeout(timer); // 컴포넌트 언마운트 시 타이머 클리어
  }, []);

  const transformUserData = async (userData: UserData) => {
    const transformedData: { role: string; content: string }[] = [];
    // userData가 null인 경우 함수 실행하지 않음
    if (!userData) {
      return transformedData;
    }
    // Adding system role data
    transformedData.push({
      role: "system",
      content: `당신은 직업 추천 봇입니다. 사용자의 개인정보를 고려하여 직업 추천 답변을 해주세요. \n\n###\n개인정보를 고려하는 우선순위는 다음과 같습니다. \n\n1. 전공\n2. 전공의 적성\n3. 경험\n4. 성향\n5. 기타 항목\n\n###\n답변의 양식은 아래와 같습니다. 사용자에게 친근한 말투로 답변해야 합니다. 1., 2., 3., 4., 5. 처럼 번호를 매겨야 합니다. \n\n1. 직업 이름: {내용}\n2. 직업 설명: {내용}\n3. 관련 학과: {내용}\n4. 관련 자격증: {내용}\n5. 추천 이유: {내용}\n\n3번 항목은 100자 이내입니다. \n5번 항목은 200자 이내입니다. \n5번 항목은 사용자의 개인정보에 근거하여 사실만을 작성합니다.`,
    });
    // Transforming user profile data
    transformedData.push({
      role: "user",
      content: `이름: ${userData.profile.name}\n성별: ${userData.profile.gender}\n나이: ${
        userData.profile.age
      }대\n취미: ${userData.profile.about_me}\n흥미 분야: ${userData.interest
        .map((interest: { interest1: string }) => interest.interest1)
        .join(", ")}\n전공: ${userData.education[0].major}\n전공의 적성: ${
        userData.education[0].major_check
      }점만점 중 3점\n경험: ${userData.experience
        .map(
          (exp: { experience_type: string; experience_content: string }) =>
            `${exp.experience_type}: ${exp.experience_content}`
        )
        .join(" / ")}\n성향: ${userData.keyword.map((kw: { type: string }) => kw.type).join(" / ")}\n\n`,
    });

    return transformedData;
  };

  //const apiEndpoint = `http://49.50.166.153:8080/jobs/recommendations/${userId}/`;
  const apiEndpoint = `http://49.50.166.153:8080/jobs/recommendations/${userId}/`;
  // 서버에서 키워드 데이터 요청
  const fetchUserData = async () => {
    try {
      // 저장된 사용자 ID를 사용하여 서버에서 사용자 데이터를 가져옵니다.
      const response = await axios.get(apiEndpoint);
      return response.data;
    } catch (error) {
      console.error("에러:", error);
    }
  };
  // user data 전송
  const saveUserData = async (data: TransformedDataItem[]) => {
    try {
      const response = await axios.post(apiEndpoint, JSON.stringify(data));
      localStorage.setItem("userData", JSON.stringify(response.data));
      navigate("/customizedCareer");
    } catch (error) {
      console.error("에러:", error);
    }
  };
  return (
    <Wrapper>
      <ContentBox>
        <Character>
          <img src={process.env.PUBLIC_URL + "/image/watingCharacter.png"} alt="characterImage" />
        </Character>
        <Title title="리쿠르탐이" />
        <Title title="맞춤 커리어를 찾고 있어요!" />
        <ProccessBox>
          {profileAnalysisSteps.map((item, index) => (
            <Proccess key={index}>
              <FaCircleCheck /> <SubTitle subtitle={item} isHome={false} />
            </Proccess>
          ))}
        </ProccessBox>
      </ContentBox>
    </Wrapper>
  );
};

export default Loading;
