import { createSlice, PayloadAction } from "@reduxjs/toolkit";

export interface UserResult {
  id: number;
  user_name: string;
  job_name: string;
  job_description: string;
  related_major: string;
  certifications: string;
  recommendation_reason: string;
  user_id: number;
}
type UserResultState = UserResult | null;

const initialState = null as UserResultState;

// Create a slice for user results
export const userResultSlice = createSlice({
  name: "userResult",
  initialState,
  reducers: {
    setUserResult: (state, action: PayloadAction<UserResult>) => {
      return action.payload;
    },
    clearUserResult: (state) => {
      return null;
    },
  },
});

// Export action creators
export const { setUserResult, clearUserResult } = userResultSlice.actions;

// Export the reducer
export default userResultSlice.reducer;
